<?php
declare(strict_types=1);namespace Atlas\Platform\PatientResources\Services;use Atlas\Platform\PatientResources\Domain\PatientResourcePolicy;use Atlas\Platform\PatientResources\Domain\PatientResourceVariant;use Atlas\Platform\PatientResources\Repositories\PatientResourceAccessRepository;use Atlas\Platform\PatientResources\Repositories\VariantRepository;use InvalidArgumentException;final class PatientResourceVariantService{public function __construct(private VariantRepository $variants,private PatientResourceAccessRepository $access,private PatientResourcePolicy $policy){}public function save(string $org,string $version,array $input,string $key,int $user):?PatientResourceVariant{if($org===''||$user<=0){return null;}if(preg_match('/^[A-Za-z0-9._:-]{8,128}$/',$key)!==1){throw new InvalidArgumentException('A valid idempotency key is required.');}if(!$this->access->isPublishedPatientEducationVersion($version,$org)){return null;}return $this->variants->save($org,$version,$this->policy->normalize($input),$key,$user);}}
